using Microsoft.EntityFrameworkCore;
using System.Linq;

class CosmosQuery
{
    // EF Core 9 Cosmos: sync I/O (ToList, SaveChanges, etc.) now throws.
    // Use async equivalents instead.
    async Task FindProducts(ProductContext ctx)
    {
        // Direct Cosmos SQL — still references c.Discriminator, which is correct
        // because we configured HasDiscriminator<string>("Discriminator") to
        // preserve the old property name for existing documents.
        var sql = "SELECT * FROM c WHERE c.Discriminator = 'Product' AND c.Sku = @sku";

        var products = await ctx.Products.Where(p => p.Sku == "ABC").ToListAsync();
    }
}

